def transform(grid):
    h, w = len(grid), len(grid[0]) if grid else 0
    if not h:
        return []
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # The dense multicolor object is the template; isolated 8s are locators.
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] != bg and grid[r][c] != 8]
    if not pts:
        return [row[:] for row in grid]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    template = [grid[r][c0:c1+1] for r in range(r0, r1+1)]
    # Locate center anchor (lower-index central row for even-height templates).
    ar, ac = (r1-r0)//2, (c1-c0)//2
    out = [row[:] for row in grid]
    for gr in range(h):
        for gc in range(w):
            if grid[gr][gc] == 8:
                tr, tc = gr-ar, gc-ac
                for dr, row in enumerate(template):
                    rr = tr+dr
                    if 0 <= rr < h:
                        for dc, v in enumerate(row):
                            cc = tc+dc
                            if 0 <= cc < w:
                                out[rr][cc] = v
    return out

